typedef unsigned char uint8;

enum EVENT
{
    EVT_SURFER_LAND,
    EVT_SURFER_WIPEOUT,
    EVT_SURFER_DUCK_DIVE,
    EVT_TRICK_REGION_CHANGE,
    EVT_TRICK_FACE_BEGIN,
    EVT_TRICK_FACE_END,
    EVT_SCORING_SERIES_END,
    EVT_SCORING_CHAIN_END
};

class EventRecipient
{
public:
    EventRecipient();
    virtual ~EventRecipient();
    virtual void OnEvent(const EVENT event, const int param1 = 0, const int param2 = 0) = 0;
};

enum TRICKREGION
{
    TREGION_FACE,
    TREGION_AIR,
    TREGION_TUBE
};

struct SurferTrick
{
    int trick_id;
    int anim_id;
    int board_anim_id;
    int flags;
    int IK_flags;
    int trickbook_type;
    int trick_type;
    uint8 button1;
    uint8 button2;
    uint8 button3;
    char button1_string[16];
    char button2_string[16];
    char button3_string[16];
    int Time;
    int Points;
};

extern SurferTrick GTrickList[];
extern const int SpecialFlag;

class SpecialMeter : public EventRecipient
{
public:
    static float ZONE_BOUNDARY;
    static float DROP_RATE;
    static float DROP_RATE_SPECIAL;
    static float DROP_RATE_SPECIAL_FACE;
    static float PERFECT_BONUS;

private:
    int playerIdx;
    float fillage;
    bool isEnabled;
    float specialTime;
    TRICKREGION trickRegion;
    bool isDoingTrick;
    int faceLink;
    float faceLinkTimer;
    float current_special_time;
    int numPerfects;

public:
    SpecialMeter();
    virtual ~SpecialMeter();
    void Initialize(const int pIdx);
    void Reset(void);
    void Update(const float dt, const TRICKREGION region, const int trickIdx, const int trickCount);
    void OnEvent(const EVENT event, const int param1 = 0, const int param2 = 0);
    void SetFillage(const float f);
    void Increase(const float f);
    void Decrease(const float f);
    void SetUpSpecialTimer();
    float GetCurrentSpecialTime() {return current_special_time;}
    bool CanRegionLink(void) const;
    bool CanFaceLink(void) const;
    float GetFillage(void) const { return fillage; }
};

void SpecialMeter::Update(const float dt, const TRICKREGION region, const int trickIdx, const int trickCount)
{	
	float	modifiedSpecialTime;

	trickRegion = region;
	isDoingTrick = (trickRegion == TREGION_AIR) || (trickRegion == TREGION_TUBE) || (trickIdx != -1);

	if (CanRegionLink())
		current_special_time += dt;
	else
		current_special_time = 0;

	// Drop rate for unenabled meter.
	if (!isEnabled)
	{
		if (region != TREGION_TUBE)
			Decrease(DROP_RATE*dt);
	}
	// Drop rate for enabled meter.
	else
	{
		// Enabled special meter drop rate for air region.
		if (trickRegion == TREGION_AIR)
		{
			// Do not decrase meter while in the air.
		}
		// Enabled special meter drop rate for tube region.
		else if (trickRegion == TREGION_TUBE)
		{
			// Do not decrase meter while in the tube.
		}
		// Enabled special meter drop rate for face region.
		else
		{
			// Decrease meter if doing a special face trick.
			if (trickIdx != -1 && GTrickList[trickIdx].flags & SpecialFlag)
			{				
				Decrease(DROP_RATE_SPECIAL_FACE*dt);
			}
			// Decrease meter if not doing a special face trick.
			else if (!isDoingTrick || trickCount >= 4)
			{
				specialTime += dt;

				// Calculate how long meter has been enabled, deducting perfect bonus.
				modifiedSpecialTime = specialTime;
				if (specialTime >= numPerfects*PERFECT_BONUS)
				{
					modifiedSpecialTime -= numPerfects*PERFECT_BONUS;
					if (modifiedSpecialTime < 0.0f)
						modifiedSpecialTime = 0.0f;
				}

				Decrease(modifiedSpecialTime*DROP_RATE_SPECIAL);
			}
		}
	}


	// Decrease face linking timer.
	if (trickRegion == TREGION_FACE)
	{
		if (!isDoingTrick && faceLinkTimer > 0.0f)
		{
			faceLinkTimer -= dt;

			// Time ran out to link face tricks.
			if (faceLinkTimer < 0.0f)
			{
				faceLink = 0;
				faceLinkTimer = 0.0f;
			}
		}	
	}

#if defined(DEBUG) && defined(TOBY)
	if (playerIdx == 0)
		frontendmanager.IGO->SetDebugText(stringx(faceLinkTimer));
#endif
}
